import {
  useState,
  useEffect,
  useMemo,
  useCallback,
  useRef,
} from 'preact/hooks';
import { CompanyHierarchyViewMode, Company } from '@/company-management/types';
import { TreeItem } from '@/company-management/components/Tree/Tree';
import {
  isCompanyAdmin,
  getCompanyHierarchy,
  assignChildCompany,
  unassignChildCompany,
} from '@/company-management/api';

/**
 * Virtual root node ID used ONLY for drag-and-drop to root level.
 * This node is hidden from UI but allows dropping companies to make them root-level.
 */
export const VIRTUAL_ROOT_ID = '__ROOT__' as const;

export const useCompanyHierarchy = (defaultExpanded: boolean = true) => {
  const [companies, setCompanies] = useState<Company[]>([]);
  const [loading, setLoading] = useState(true);
  const [viewMode, setViewMode] = useState<CompanyHierarchyViewMode>(
    CompanyHierarchyViewMode.IS_LOADING
  );
  const [expandedIds, setExpandedIds] = useState<Set<string>>(new Set());
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [isAdminUser, setIsAdminUser] = useState(false);
  const defaultExpandedRef = useRef(defaultExpanded);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);

  const cloneCompanies = useCallback((items: Company[]): Company[] => {
    return items.map((company) => ({
      ...company,
      parent_company: company.parent_company
        ? { ...company.parent_company }
        : null,
      child_companies: cloneCompanies(company.child_companies || []),
    }));
  }, []);

  useEffect(() => {
    const checkAdminAndFetchData = async () => {
      setLoading(true);
      setViewMode(CompanyHierarchyViewMode.IS_LOADING);
      setErrorMessage(null);

      try {
        // Check if user is admin first
        const adminStatus = await isCompanyAdmin();
        setIsAdminUser(adminStatus);

        // If not admin, show no access
        if (!adminStatus) {
          setViewMode(CompanyHierarchyViewMode.NO_ACCESS);
          setLoading(false);
          return;
        }

        // Fetch company hierarchy data
        const companies = await getCompanyHierarchy();
        setCompanies(companies);

        // Set initial expansion state based on defaultExpanded prop
        if (defaultExpandedRef.current) {
          const allIds = new Set<string>();
          allIds.add(VIRTUAL_ROOT_ID); // Always expand virtual root
          const collectIds = (comps: Company[]) => {
            comps.forEach((comp) => {
              allIds.add(comp.id);
              if (comp.child_companies?.length > 0) {
                collectIds(comp.child_companies);
              }
            });
          };
          collectIds(companies);
          setExpandedIds(allIds);
        } else {
          // Collapsed by default
          setExpandedIds(new Set([VIRTUAL_ROOT_ID]));
        }

        // Set viewMode based on data
        if (companies.length === 0) {
          setViewMode(CompanyHierarchyViewMode.IS_EMPTY);
        } else {
          setViewMode(CompanyHierarchyViewMode.SHOW_STRUCTURE);
        }
      } catch (error) {
        setCompanies([]);
        setExpandedIds(new Set());
        setErrorMessage(
          error instanceof Error ? error.message : 'Failed to load company hierarchy'
        );
        setViewMode(CompanyHierarchyViewMode.IS_ERROR);
      } finally {
        setLoading(false);
      }
    };

    checkAdminAndFetchData();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []); // Run only on mount

  // Convert nested companies to flat TreeItem array with is_admin metadata
  const treeItems: TreeItem[] = useMemo(() => {
    const items: TreeItem[] = [];
    const processedIds = new Set<string>();

    // Add virtual root for drag-and-drop (hidden in UI)
    items.push({
      id: VIRTUAL_ROOT_ID,
      parentId: null,
      label: '', // Empty label - will be hidden in UI
      metadata: { is_admin: true }, // Virtual root is always admin
    });

    const flattenCompanies = (
      comps: Company[],
      parentId: string | null = null
    ) => {
      comps.forEach((company) => {
        // Avoid duplicate entries
        if (!processedIds.has(company.id)) {
          // Root companies have virtual root as parent for drag-and-drop
          const actualParentId = parentId === null ? VIRTUAL_ROOT_ID : parentId;
          items.push({
            id: company.id,
            parentId: actualParentId,
            label: company.name,
            metadata: {
              is_admin: company.is_admin,
              hasChildren: (company.child_companies?.length ?? 0) > 0,
            },
          });
          processedIds.add(company.id);
        }

        // Process child companies (only one level deep)
        if (company.child_companies?.length > 0) {
          flattenCompanies(company.child_companies, company.id);
        }
      });
    };

    flattenCompanies(companies);
    return items;
  }, [companies]);

  const expandAll = useCallback(() => {
    const allIds = new Set(treeItems.map((item) => item.id));
    setExpandedIds(allIds);
  }, [treeItems]);

  const collapseAll = useCallback(() => {
    setExpandedIds(new Set([VIRTUAL_ROOT_ID]));
  }, []);

  const canDrop = useCallback(
    (dragId: string, targetId: string) => {
      if (dragId === targetId) return false;

      // Only allow dropping on VIRTUAL_ROOT or root companies (with VIRTUAL_ROOT as parent)
      // This enforces only one level of nesting
      const targetItem = treeItems.find((item) => item.id === targetId);
      if (!targetItem) return false;

      // Target must be VIRTUAL_ROOT or a root company
      const isVirtualRoot = targetItem.id === VIRTUAL_ROOT_ID;
      const isRootCompany = targetItem.parentId === VIRTUAL_ROOT_ID;

      if (!isVirtualRoot && !isRootCompany) return false;

      // Prevent dropping a parent into its own child
      const dragItem = treeItems.find((item) => item.id === dragId);
      if (!dragItem) return false;

      // Check if target is a child of the dragged item
      const isChild = treeItems.some(
        (item) => item.id === targetId && item.parentId === dragId
      );

      if (isChild) return false;

      // CRITICAL: Prevent creating 3+ level hierarchy
      // Companies with children can ONLY be dropped on VIRTUAL_ROOT (to remain/become root-level)
      // Companies without children CAN be dropped on any root company
      const dragHasChildren = dragItem.metadata?.hasChildren === true;
      if (dragHasChildren && !isVirtualRoot) {
        return false; // Prevent parent company from being nested under another company
      }

      return true;
    },
    [treeItems]
  );

  // API call to assign/unassign child company
  const handleMoveAPI = useCallback(
    async (
      childCompanyId: string,
      newParentId: string | null,
      oldParentId: string | null,
      previousCompanies: Company[]
    ) => {
      try {
        setErrorMessage(null);
        // If moving to root level (virtual root or null), unassign from current parent
        if (!newParentId || newParentId === VIRTUAL_ROOT_ID) {
          if (oldParentId && oldParentId !== VIRTUAL_ROOT_ID) {
            await unassignChildCompany(childCompanyId);
          }
        } else {
          // Moving to a new parent
          // First, unassign from old parent if exists
          if (oldParentId && oldParentId !== VIRTUAL_ROOT_ID) {
            await unassignChildCompany(childCompanyId);
          }
          // Then assign to new parent
          await assignChildCompany(newParentId, childCompanyId);
        }

        // Reload data from server after successful API call
        const updatedCompanies = await getCompanyHierarchy();
        setCompanies(updatedCompanies);
      } catch (error) {
        setErrorMessage(
          error instanceof Error ? error.message : 'Failed to update company hierarchy'
        );
        setCompanies(previousCompanies);

        try {
          const updatedCompanies = await getCompanyHierarchy();
          setCompanies(updatedCompanies);
        } catch (reloadError) {
          // Keep the rolled back state if the reload also fails.
        }
      }
    },
    []
  );

  const onMove = useCallback(
    (args: { id: string; newParentId: string }) => {
      // Store old parent ID before making changes
      let oldParentId: string | null | undefined = null;
      const movedItem = treeItems.find((item) => item.id === args.id);
      if (movedItem) {
        oldParentId = movedItem.parentId;
      }

      let previousCompaniesSnapshot: Company[] = [];
      let didMove = false;

      // Update local state immediately for responsive UI
      setCompanies((prevCompanies) => {
        previousCompaniesSnapshot = cloneCompanies(prevCompanies);

        // Find the company being moved and remove it from its current location
        let movedCompany: Company | null = null;

        const removeFromTree = (comps: Company[]): Company[] => {
          return comps.filter((comp) => {
            if (comp.id === args.id) {
              movedCompany = comp;
              return false; // Remove it
            }
            // Recursively check children
            if (comp.child_companies?.length > 0) {
              const childCompanies = removeFromTree(comp.child_companies);
              comp.child_companies = childCompanies;
            }
            return true;
          });
        };

        const newTree = removeFromTree(cloneCompanies(prevCompanies));

        if (!movedCompany) return prevCompanies; // Company not found
        didMove = true;

        // TypeScript: ensure movedCompany is treated as Company
        const sourceCompany: Company = movedCompany as Company;

        // Check if moving to root level (virtual root)
        if (!args.newParentId || args.newParentId === VIRTUAL_ROOT_ID) {
          // Moving to root level
          const updatedCompany: Company = {
            ...sourceCompany,
            parent_company: null,
          };
          // Add directly to root array
          return [...newTree, updatedCompany];
        }

        // Moving to another parent - find parent name for the relationship
        const targetParentName =
          treeItems.find((t) => t.id === args.newParentId)?.label || '';
        const updatedCompany: Company = {
          ...sourceCompany,
          parent_company: {
            id: args.newParentId,
            name: targetParentName,
          },
        };

        // Add to new parent's children
        const addToTree = (comps: Company[]): Company[] => {
          return comps.map((comp) => {
            if (comp.id === args.newParentId) {
              return {
                ...comp,
                child_companies: [
                  ...(comp.child_companies || []),
                  updatedCompany,
                ],
              };
            }
            if (comp.child_companies?.length > 0) {
              return {
                ...comp,
                child_companies: addToTree(comp.child_companies),
              };
            }
            return comp;
          });
        };

        return addToTree(newTree);
      });

      // Persist the move after local state update
      // Convert undefined to null for API call
      const normalizedOldParentId =
        oldParentId === undefined ? null : oldParentId;
      if (!didMove) return;

      handleMoveAPI(
        args.id,
        args.newParentId,
        normalizedOldParentId,
        previousCompaniesSnapshot
      );
    },
    [cloneCompanies, handleMoveAPI, treeItems]
  );

  return {
    companies,
    setCompanies,
    treeItems,
    loading,
    setLoading,
    viewMode,
    setViewMode,
    expandedIds,
    setExpandedIds,
    selectedId,
    setSelectedId,
    expandAll,
    collapseAll,
    canDrop,
    onMove,
    isAdmin: isAdminUser,
    errorMessage,
  };
};
