import { FunctionComponent } from 'preact';
import { useMemo, useCallback, useRef } from 'preact/hooks';
import { Checkbox } from '@adobe-commerce/elsie/components';
import { polyfill } from 'mobile-drag-drop';
import 'mobile-drag-drop/default.css';
import 'mobile-drag-drop/icons.css';
import './Tree.css';

// Initialize mobile-drag-drop polyfill once
let polyfillInitialized = false;
if (typeof window !== 'undefined' && !polyfillInitialized) {
  // Required for iOS 10+
  try {
    window.addEventListener('touchmove', () => {}, { passive: false });
  } catch (e) {}
  
  polyfill({
    holdToDrag: 300,
    tryFindDraggableTarget: (event: TouchEvent) => {
      let element = event.target as HTMLElement;
      while (element && element !== document.body) {
        if (element.getAttribute('draggable') === 'true') {
          return element;
        }
        element = element.parentElement as HTMLElement;
      }
      return undefined;
    },
  });
  
  // Required: prevent context menu on long press
  document.addEventListener('contextmenu', (e) => {
    const target = e.target as HTMLElement;
    if (target.closest('[draggable="true"]')) {
      e.preventDefault();
    }
  });
  
  polyfillInitialized = true;
}

export interface TreeItem {
  id: string;
  parentId?: string | null;
  label: string;
  metadata?: Record<string, unknown>;
}

export interface RenderNodeArgs {
  item: TreeItem;
  level: number;
  expanded: boolean;
  selected: boolean;
  hasChildren: boolean;
  toggle: () => void;
  select: () => void;
  // Optional Elsie-friendly render helpers
  expander?: () => any;
  checkbox?: () => any;
  icon?: () => any;
}

export interface TreeProps {
  items: TreeItem[];
  rootId?: string | null;
  className?: string;
  expandedIds: Set<string>;
  selectedId?: string | null;
  selectedIds?: Set<string>;
  onExpandedChange: (next: Set<string>) => void;
  onSelectedChange?: (id: string | null) => void;
  onSelectedIdsChange?: (ids: Set<string>) => void;
  renderNode: (args: RenderNodeArgs) => any;
  role?: 'tree' | 'list' | 'grid'; // default 'tree'
  // Sorting behavior (optional)
  preserveOrder?: boolean; // If true, preserve the original order of items. If false/undefined, sort alphabetically by label
  // Drag & Drop (optional)
  draggable?: (item: TreeItem) => boolean;
  canDrop?: (dragId: string, targetId: string) => boolean;
  onMove?: (args: { id: string; newParentId: string }) => void;
  // Checkable (optional)
  isCheckable?: (item: TreeItem) => boolean;
  checkedIds?: Set<string>;
  onCheckedChange?: (next: Set<string>) => void;
  // Checkbox behavior (optional)
  biDirectionalChecking?: boolean; // If true, checking a node directly marks it as checked. If false, uses descendant-based logic (default: false)
  // Optional Elsie-friendly render-props to build UI primitives
  renderExpander?: (args: { expanded: boolean; hasChildren: boolean; toggle: () => void }) => any;
  renderCheckbox?: (args: { checked: boolean; indeterminate: boolean; onCheck: () => void }) => any;
  renderIcon?: (args: { item: TreeItem; level: number; hasChildren: boolean; expanded: boolean }) => any;
}

const buildChildrenMap = (items: TreeItem[], preserveOrder: boolean = false): Map<string | null, TreeItem[]> => {
  const byParent = new Map<string | null, TreeItem[]>();
  for (const item of items) {
    const key = (item.parentId ?? null) as string | null;
    const list = byParent.get(key) ?? [];
    list.push(item);
    byParent.set(key, list);
  }
  
  // Apply sorting based on preserveOrder flag
  if (!preserveOrder) {
    // Default behavior: stable sort by label for determinism
    for (const [, list] of byParent) {
      list.sort((a, b) => a.label.localeCompare(b.label));
    }
  }
  // If preserveOrder is true, keep the original order (e.g., sorted by sort_order)
  
  return byParent;
};

export const Tree: FunctionComponent<TreeProps> = ({
  items,
  rootId = null,
  className,
  expandedIds,
  selectedId = null,
  selectedIds,
  onExpandedChange,
  onSelectedChange,
  onSelectedIdsChange,
  renderNode,
  role = 'tree',
  preserveOrder = false,
  draggable,
  canDrop,
  onMove,
  isCheckable,
  checkedIds,
  onCheckedChange,
  biDirectionalChecking = false,
  renderExpander,
  renderCheckbox,
  renderIcon,
}) => {
  const byParent = useMemo(() => buildChildrenMap(items, preserveOrder), [items, preserveOrder]);
  const draggingIdRef = useRef<string | null>(null);
  const multiSelectRef = useRef<boolean>(false);

  const byId = useMemo(() => new Map(items.map((i) => [i.id, i] as const)), [items]);

  const collectDescendants = (
    byParentMap: Map<string | null, TreeItem[]>,
    id: string
  ): string[] => {
    const out: string[] = [];
    const stack = [id];
    while (stack.length) {
      const cur = stack.pop()!;
      const children = byParentMap.get(cur) ?? [];
      for (const ch of children) {
        out.push(ch.id);
        stack.push(ch.id);
      }
    }
    return out;
  };

  const getDescendants = useCallback(
    (id: string): string[] => {
      return collectDescendants(byParent, id);
    },
    [byParent]
  );

  const isNodeCheckable = useCallback((item: TreeItem) => (isCheckable ? isCheckable(item) : true), [isCheckable]);

  const computeCheckedState = useCallback(
    (id: string): { checked: boolean; indeterminate: boolean } => {
      const item = byId.get(id);
      if (!item) return { checked: false, indeterminate: false };
      
      const set = checkedIds ?? new Set<string>();
      
      if (biDirectionalChecking) {
        // If this node is directly checked, show it as checked
        if (set.has(id)) {
          return { checked: true, indeterminate: false };
        }
        
        // Otherwise, check descendants to determine indeterminate state
        const descendants = getDescendants(id).filter((nid) => {
          const node = byId.get(nid);
          return node ? isNodeCheckable(node) : false;
        });
        
        if (descendants.length === 0) return { checked: false, indeterminate: false };
        
        const numCheckedDescendants = descendants.reduce((acc, nid) => (set.has(nid) ? acc + 1 : acc), 0);
        
        if (numCheckedDescendants === 0) return { checked: false, indeterminate: false };
        return { checked: false, indeterminate: true };
      }
      
      // Check if node and ALL descendants are checked
      const all = [id, ...getDescendants(id)].filter((nid) => {
          const node = byId.get(nid);
          return node ? isNodeCheckable(node) : false;
        });
        
        if (all.length === 0) return { checked: false, indeterminate: false };
        
        const numChecked = all.reduce((acc, nid) => (set.has(nid) ? acc + 1 : acc), 0);
        
        if (numChecked === 0) return { checked: false, indeterminate: false };
        if (numChecked === all.length) return { checked: true, indeterminate: false };
        return { checked: false, indeterminate: true };
    },
    [byId, getDescendants, isNodeCheckable, checkedIds, biDirectionalChecking]
  );

  const toggleCheck = useCallback(
    (id: string) => {
      if (!onCheckedChange) return;
      
      const set = new Set(checkedIds ?? []);
      const { checked } = computeCheckedState(id);
      
      // 1) Handle downward propagation: check/uncheck this node and all descendants
      const descendants = getDescendants(id);
      const targets = [id, ...descendants].filter((nid) => {
        const node = byId.get(nid);
        return node ? isNodeCheckable(node) : false;
      });
      
      if (checked) {
        // Unchecking: remove this node and all descendants
        for (const nid of targets) set.delete(nid);
      } else {
        // Checking: add this node and all descendants
        for (const nid of targets) set.add(nid);
      }
      
      // 2) Handle upward propagation: only check ancestors when checking
      if (biDirectionalChecking && !checked) {
        const item = byId.get(id);
        if (item) {
          let currentParentId = item.parentId;
          while (currentParentId) {
            const parentItem = byId.get(currentParentId);
            if (!parentItem || !isNodeCheckable(parentItem)) break;
            
            // When checking a child, check the parent
            set.add(currentParentId);
            
            // Move up to the next parent
            currentParentId = parentItem.parentId;
          }
        }
      }
      
      onCheckedChange(set);
    },
    [checkedIds, onCheckedChange, computeCheckedState, getDescendants, byId, isNodeCheckable, biDirectionalChecking]
  );

  // Default checkbox renderer that handles tri-state logic
  const defaultCheckboxRenderer = useCallback(
    (args: { checked: boolean; indeterminate: boolean; onCheck: () => void }) => {
      return (
        <Checkbox
          name={`tree-checkbox-${Math.random().toString(36).substr(2, 9)}`}
          checked={args.checked}
          indeterminate={args.indeterminate}
          onChange={args.onCheck}
        />
      );
    },
    []
  );

  const toggle = useCallback(
    (id: string) => {
      const next = new Set(expandedIds);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      onExpandedChange(next);
    },
    [expandedIds, onExpandedChange]
  );

  const select = useCallback(
    (id: string) => {
      // If the node is checkable, toggle its checkbox state
      const item = byId.get(id);
      if (item && isNodeCheckable(item) && onCheckedChange) {
        toggleCheck(id);
      }

      if (!onSelectedIdsChange) {
        onSelectedChange?.(id);
        return;
      }

      const isMulti = !!multiSelectRef.current;
      const next = isMulti ? new Set(selectedIds ?? []) : new Set<string>();
      
      if (isMulti && next.has(id)) {
        next.delete(id);
      } else {
        next.add(id);
      }
      
      onSelectedIdsChange(next);
      multiSelectRef.current = false;
    },
    [onSelectedChange, onSelectedIdsChange, selectedIds, byId, isNodeCheckable, onCheckedChange, toggleCheck]
  );

  const renderSubtree = (parentId: string | null, level: number): any => {
    const children = byParent.get(parentId) ?? [];
    if (!children.length) return null;
    const ulClass = level === 1 ? (className ?? 'acm-tree') : 'acm-tree__group';
    return (
      <ul role={level === 1 ? (role as any) : 'group'} className={ulClass}>
        {children.map((item, index) => {
          const childHasChildren = (byParent.get(item.id) ?? []).length > 0;
          const isExpanded = expandedIds.has(item.id);
          const isSelected = (selectedIds ? selectedIds.has(item.id) : (selectedId === item.id));
          const isDraggable = !!draggable?.(item);
          const allowDrop = (dragId: string) => (canDrop ? canDrop(dragId, item.id) : dragId !== item.id);
          // Optional helpers for Elsie-based UIs
          const expanderFactory = childHasChildren
            ? () => (renderExpander ? renderExpander({ expanded: isExpanded, hasChildren: childHasChildren, toggle: () => toggle(item.id) }) : null)
            : undefined;
          const checkboxFactory = (() => {
            if (!onCheckedChange) return undefined;
            const nodeObj = byId.get(item.id);
            if (!nodeObj || !isNodeCheckable(nodeObj)) return undefined;
            const s = computeCheckedState(item.id);
            const checkboxRenderer = renderCheckbox || defaultCheckboxRenderer;
            return () => checkboxRenderer({ checked: s.checked, indeterminate: s.indeterminate, onCheck: () => toggleCheck(item.id) });
          })();
          const iconFactory = renderIcon
            ? () => renderIcon({ item, level, hasChildren: childHasChildren, expanded: isExpanded })
            : undefined;

          const node = renderNode({
            item,
            level,
            expanded: isExpanded,
            selected: !!isSelected,
            hasChildren: childHasChildren,
            toggle: () => toggle(item.id),
            select: () => select(item.id),
            ...(expanderFactory ? { expander: expanderFactory } : {}),
            ...(checkboxFactory ? { checkbox: checkboxFactory } : {}),
            ...(iconFactory ? { icon: iconFactory } : {}),
          });
          return (
            <li
              key={item.id}
              role="treeitem"
              className="acm-tree__item"
              data-level={level}
              aria-expanded={childHasChildren ? isExpanded : undefined}
              aria-selected={isSelected || undefined}
              aria-level={level as any}
              aria-setsize={children.length as any}
              aria-posinset={(index + 1) as any}
              draggable={isDraggable}
              onMouseDown={(e) => {
                // Command (mac) or Ctrl (win/linux) enables multi-select
                multiSelectRef.current = !!(e.metaKey || e.ctrlKey);
              }}
              onDragStart={(e) => {
                e.stopPropagation();
                if (!isDraggable) return;
                draggingIdRef.current = item.id;
                try { e.dataTransfer?.setData('text/plain', item.id); } catch {}
              }}
              onDragEnter={(e) => {
                // Required by mobile-drag-drop polyfill
                e.preventDefault();
              }}
              onDragOver={(e) => {
                e.stopPropagation();
                const dragId = draggingIdRef.current ?? (e.dataTransfer?.getData('text/plain') || '');
                if (dragId && allowDrop(dragId)) {
                  e.preventDefault();
                }
              }}
              onDrop={(e) => {
                e.stopPropagation();
                const dragId = draggingIdRef.current ?? (e.dataTransfer?.getData('text/plain') || '');
                draggingIdRef.current = null;
                if (dragId && allowDrop(dragId)) {
                  onMove?.({ id: dragId, newParentId: item.id });
                }
              }}
            >
              {node}
              {childHasChildren && isExpanded ? renderSubtree(item.id, level + 1) : null}
            </li>
          );
        })}
      </ul>
    );
  };

  return <div className="acm-tree-root">{renderSubtree(rootId, 1)}</div>;
};

export default Tree;
