import { FunctionComponent } from 'preact';
import { HTMLAttributes } from 'preact/compat';
import { useState, useCallback, useEffect, useRef } from 'preact/hooks';
import { classes } from '@adobe-commerce/elsie/lib';
import { Button, InLineAlert } from '@adobe-commerce/elsie/components';
import { useText } from '@adobe-commerce/elsie/i18n';
import { deleteCompanyUser, updateCompanyUserStatus } from '@/company-management/api';
import type { CompanyUserStatus } from '@/company-management/types';
import { useInLineAlert, useCustomerCompanyInfo } from '@/company-management/hooks';
import '@/company-management/components/CompanyUsersManagementModal/CompanyUsersManagementModal.css';

export interface CompanyUsersManagementModalProps extends Omit<HTMLAttributes<HTMLDivElement>, 'onClose'> {
  /** The ID of the user to manage */
  userId: string;
  /** The current status of the user */
  userStatus: CompanyUserStatus;
  /** Callback function called when the modal should be closed */
  onClose: () => void;
  /** Whether the modal is currently open */
  isOpen?: boolean;
  /** Callback for success messages */
  onSuccess?: (message: string) => void;
}

export const CompanyUsersManagementModal: FunctionComponent<CompanyUsersManagementModalProps> = ({
  className,
  userId,
  userStatus,
  onClose,
  isOpen = false,
  onSuccess,
  ...props
}) => {
  const [isDeleting, setIsDeleting] = useState(false);
  const [isTogglingStatus, setIsTogglingStatus] = useState(false);
  const { inLineAlertProps, showError, clearAlert } = useInLineAlert();
  const { companyInfo } = useCustomerCompanyInfo();
  
  // Refs for accessibility
  const modalRef = useRef<HTMLDivElement>(null);
  const previousFocusRef = useRef<HTMLElement | null>(null);
  const titleId = `modal-title-${userId}`;
  const descriptionId = `modal-desc-${userId}`;

  // Text translations
  const translations = useText({
    title: 'Company.CompanyUsers.managementModal.title',
    setActiveText: 'Company.CompanyUsers.managementModal.setActiveText',
    setInactiveText: 'Company.CompanyUsers.managementModal.setInactiveText',
    deleteText: 'Company.CompanyUsers.managementModal.deleteText',
    setActiveButton: 'Company.CompanyUsers.managementModal.setActiveButton',
    setInactiveButton: 'Company.CompanyUsers.managementModal.setInactiveButton',
    settingActiveButton: 'Company.CompanyUsers.managementModal.settingActiveButton',
    settingInactiveButton: 'Company.CompanyUsers.managementModal.settingInactiveButton',
    deleteButton: 'Company.CompanyUsers.managementModal.deleteButton',
    deletingButton: 'Company.CompanyUsers.managementModal.deletingButton',
    cancelButton: 'Company.CompanyUsers.managementModal.cancelButton',
    setActiveErrorGeneric: 'Company.CompanyUsers.managementModal.setActiveErrorGeneric',
    setActiveErrorSpecific: 'Company.CompanyUsers.managementModal.setActiveErrorSpecific',
    setInactiveErrorGeneric: 'Company.CompanyUsers.managementModal.setInactiveErrorGeneric',
    setInactiveErrorSpecific: 'Company.CompanyUsers.managementModal.setInactiveErrorSpecific',
    deleteErrorGeneric: 'Company.CompanyUsers.managementModal.deleteErrorGeneric',
    deleteErrorSpecific: 'Company.CompanyUsers.managementModal.deleteErrorSpecific',
    setActiveSuccess: 'Company.CompanyUsers.managementModal.setActiveSuccess',
    setInactiveSuccess: 'Company.CompanyUsers.managementModal.setInactiveSuccess',
    deleteSuccess: 'Company.CompanyUsers.managementModal.deleteSuccess',
    ariaCloseModal: 'Company.CompanyUsers.managementModal.ariaLabels.closeModal',
    ariaModalDescription: 'Company.CompanyUsers.managementModal.ariaLabels.modalDescription',
  });

  const replaceCompanyNamePlaceholder = useCallback((message: string): string => {
    const companyName = companyInfo?.companyName || '';
    return message.replace(/%1/g, companyName);
  }, [companyInfo?.companyName]);

  const handleToggleStatus = useCallback(async () => {
    if (isTogglingStatus) return;
    
    const newStatus = userStatus === 'ACTIVE' ? 'INACTIVE' : 'ACTIVE';
    const isActivating = newStatus === 'ACTIVE';
    
    setIsTogglingStatus(true);
    clearAlert();
    try {
      const result = await updateCompanyUserStatus({ id: userId, status: newStatus });
      if (result.success) {
        const successMsg = isActivating ? translations.setActiveSuccess : translations.setInactiveSuccess;
        if (onSuccess) {
          onSuccess(successMsg);
        }
        onClose();
      } else {
        const errorMsg = isActivating ? translations.setActiveErrorSpecific : translations.setInactiveErrorSpecific;
        showError(replaceCompanyNamePlaceholder(errorMsg));
      }
    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : (isActivating ? translations.setActiveErrorGeneric : translations.setInactiveErrorGeneric);
      showError(replaceCompanyNamePlaceholder(errorMessage));
    } finally {
      setIsTogglingStatus(false);
    }
  }, [userId, userStatus, onClose, isTogglingStatus, clearAlert, showError, replaceCompanyNamePlaceholder, translations.setActiveErrorSpecific, translations.setInactiveErrorSpecific, translations.setActiveErrorGeneric, translations.setInactiveErrorGeneric, translations.setActiveSuccess, translations.setInactiveSuccess, onSuccess]);

  const handleDelete = useCallback(async () => {
    if (isDeleting) return;
    
    setIsDeleting(true);
    clearAlert();
    try {
      const result = await deleteCompanyUser({ id: userId });
      if (result.success) {
        if (onSuccess) {
          onSuccess(translations.deleteSuccess);
        }
        onClose();
      } else {
        showError(replaceCompanyNamePlaceholder(translations.deleteErrorSpecific));
      }
    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : translations.deleteErrorGeneric;
      showError(replaceCompanyNamePlaceholder(errorMessage));
    } finally {
      setIsDeleting(false);
    }
  }, [userId, onClose, isDeleting, clearAlert, showError, replaceCompanyNamePlaceholder, translations.deleteErrorSpecific, translations.deleteErrorGeneric, translations.deleteSuccess, onSuccess]);

  const handleCancel = useCallback(() => {
    clearAlert();
    onClose();
  }, [onClose, clearAlert]);

  // Handle Escape key
  const handleKeyDown = useCallback((event: KeyboardEvent) => {
    if (event.key === 'Escape') {
      clearAlert();
      onClose();
    }
    
    // Focus trapping
    if (event.key === 'Tab') {
      const modal = modalRef.current;
      if (!modal) return;
      
      const focusableElements = modal.querySelectorAll(
        'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])'
      );
      const firstElement = focusableElements[0] as HTMLElement;
      const lastElement = focusableElements[focusableElements.length - 1] as HTMLElement;
      
      if (event.shiftKey) {
        // Shift + Tab
        if (document.activeElement === firstElement) {
          lastElement.focus();
          event.preventDefault();
        }
      } else if (document.activeElement === lastElement) {
        // Tab
        firstElement.focus();
        event.preventDefault();
      }
    }
  }, [onClose, clearAlert]);

  const handleOverlayClick = useCallback((event: MouseEvent) => {
    if (event.target === event.currentTarget) {
      clearAlert();
      onClose();
    }
  }, [onClose, clearAlert]);

  const handleCloseClick = useCallback(() => {
    clearAlert();
    onClose();
  }, [onClose, clearAlert]);

  // Focus management and event listeners
  useEffect(() => {
    if (isOpen) {
      // Store current focus
      previousFocusRef.current = document.activeElement as HTMLElement;
      
      // Add keyboard event listener
      document.addEventListener('keydown', handleKeyDown);
      
      // Focus the modal after a brief delay to ensure it's rendered
      setTimeout(() => {
        const modal = modalRef.current;
        if (modal) {
          const firstButton = modal.querySelector('button') as HTMLElement;
          if (firstButton) {
            firstButton.focus();
          } else {
            modal.focus();
          }
        }
      }, 100);
      
      return () => {
        document.removeEventListener('keydown', handleKeyDown);
      };
    }
    
    // Restore focus when modal closes
    if (previousFocusRef.current) {
      previousFocusRef.current.focus();
    }
  }, [isOpen, handleKeyDown]);

  if (!isOpen) {
    return null;
  }

  return (
    <div 
      className={classes(['company-management-company-users-management-modal-overlay', className])}
      onClick={handleOverlayClick}
      {...props}
    >
      <div 
        ref={modalRef}
        className="company-management-company-users-management-modal"
        role="dialog"
        aria-modal="true"
        aria-labelledby={titleId}
        aria-describedby={descriptionId}
        tabIndex={-1}
      >
        <div className="company-management-company-users-management-modal__header">
          <h2 
            id={titleId}
            className="company-management-company-users-management-modal__title"
          >
            {translations.title}
          </h2>
          <button
            className="company-management-company-users-management-modal__close"
            onClick={handleCloseClick}
            aria-label={translations.ariaCloseModal}
          >
            ×
          </button>
        </div>
        
        <div 
          id={descriptionId}
          className="company-management-company-users-management-modal__content"
        >
          <p className="company-management-company-users-management-modal__text">
            {userStatus === 'ACTIVE' ? translations.setInactiveText : translations.setActiveText}
          </p>
          <p className="company-management-company-users-management-modal__text">
            {translations.deleteText}
          </p>
        </div>

        {inLineAlertProps?.text && (
          <div 
            className="company-management-company-users-management-modal__alert"
            role="alert"
            aria-live="assertive"
          >
            <InLineAlert
              type="error"
              heading={inLineAlertProps.text}
              icon={inLineAlertProps.icon}
              data-testid="companyUsersManagementModalAlert"
            />
          </div>
        )}

        <div className="company-management-company-users-management-modal__actions">
          <Button
            variant="primary"
            onClick={handleToggleStatus}
            disabled={isTogglingStatus}
            className="company-management-company-users-management-modal__button-primary"
          >
            {isTogglingStatus 
              ? (userStatus === 'ACTIVE' ? translations.settingInactiveButton : translations.settingActiveButton)
              : (userStatus === 'ACTIVE' ? translations.setInactiveButton : translations.setActiveButton)
            }
          </Button>
          
          <Button
            variant="tertiary"
            onClick={handleDelete}
            disabled={isDeleting}
            className="company-management-company-users-management-modal__button-delete"
          >
            {isDeleting ? translations.deletingButton : translations.deleteButton}
          </Button>
          
          <Button
            variant="secondary"
            onClick={handleCancel}
            className="company-management-company-users-management-modal__button-cancel"
          >
            {translations.cancelButton}
          </Button>
        </div>
      </div>
    </div>
  );
};
