import { FunctionComponent } from 'preact';
import { memo } from 'preact/compat';
import {
  Button,
  Card,
  Header,
  InLineAlert,
  Tag,
} from '@adobe-commerce/elsie/components';
import { classes, Slot } from '@adobe-commerce/elsie/lib';
import { Tree } from '../Tree/Tree';
import { CompanyHierarchyContentProps } from '@/company-management/types';
import { VIRTUAL_ROOT_ID } from '@/company-management/hooks';
import './CompanyHierarchyContent.css';

/**
 * CompanyHierarchyContent component for managing company hierarchy
 * Displays a tree view of companies with drag-and-drop support
 * Only one level of nesting is allowed (parent → child)
 */
export const CompanyHierarchyContent: FunctionComponent<CompanyHierarchyContentProps> = memo(({
  className,
  withHeader = false,
  errorMessage,
  treeItems,
  expandedIds,
  setExpandedIds,
  selectedId,
  setSelectedId,
  expandAll,
  collapseAll,
  canDrop,
  onMove,
  slots,
  showAdminBadge = false,
  translations,
}) => {
  return (
    <div className={classes(['account-company-hierarchy', className])}>
      {withHeader ? (
        <Header
          title={translations.containerTitle}
          divider={true}
          className="company-hierarchy__title"
        />
      ) : null}
      {errorMessage ? (
        <InLineAlert
          className="company-hierarchy-alert"
          type="error"
          variant="secondary"
          heading={translations.moveError}
        />
      ) : null}
      <Slot
        name="Actions"
        slot={slots?.Actions}
        context={{
          expandAll,
          collapseAll,
          expandedIds,
          setExpandedIds,
          treeItemsCount: treeItems.length,
        }}
      >
        <Card
          variant="secondary"
          className="company-hierarchy-toolbar-card company-hierarchy-toolbar-card--spaced"
        >
          <div
            className="company-hierarchy-toolbar"
            role="toolbar"
            aria-label="Company hierarchy actions"
          >
            <Button
              type="button"
              variant="secondary"
              onClick={expandAll}
              aria-label={translations.expandAllNodes}
            >
              {translations.expandAll}
            </Button>
            <Button
              type="button"
              variant="secondary"
              onClick={collapseAll}
              aria-label={translations.collapseAllNodes}
            >
              {translations.collapseAll}
            </Button>
          </div>
        </Card>
      </Slot>

      <div className="company-hierarchy-tree-card">
        <Tree
          items={treeItems}
          expandedIds={expandedIds}
          selectedId={selectedId}
          onExpandedChange={setExpandedIds}
          onSelectedChange={setSelectedId}
          draggable={(item) => {
            // Virtual root is never draggable
            if (item.id === VIRTUAL_ROOT_ID) return false;
            return true;
          }}
          canDrop={canDrop}
          onMove={onMove}
          preserveOrder={false}
          renderExpander={({ expanded, toggle }) => (
            <button
              type="button"
              className="company-hierarchy-expander"
              aria-label={
                expanded ? translations.collapse : translations.expand
              }
              onClick={(e) => {
                e.stopPropagation();
                toggle();
              }}
            >
              <span
                className={`company-hierarchy-chevron ${
                  expanded ? 'is-expanded' : ''
                }`}
              />
            </button>
          )}
          renderNode={({ item, hasChildren, expander, select }) => {
            // Hide virtual root from UI
            if (item.id === VIRTUAL_ROOT_ID) {
              return null;
            }

            // Root companies have virtual root as parent
            const isRootCompany = item.parentId === VIRTUAL_ROOT_ID;

            return (
              <div className="company-hierarchy-row" onClick={select}>
                {!isRootCompany && (
                  <span className="company-hierarchy-handle" aria-hidden />
                )}
                <span
                  className={`company-hierarchy-icon ${
                    isRootCompany ? 'is-root' : ''
                  }`}
                  aria-hidden
                />
                <div className="company-hierarchy-info">
                  <span className="company-hierarchy-label">{item.label}</span>
                  {showAdminBadge && item.metadata?.is_admin && <Tag label="Admin" />}
                </div>
                {hasChildren && expander ? (
                  <span
                    className="company-hierarchy-expander-wrapper"
                    onClick={(e) => e.stopPropagation()}
                  >
                    {expander()}
                  </span>
                ) : null}
              </div>
            );
          }}
        />
      </div>
    </div>
  );
});
