import { FunctionComponent } from 'preact';
import { useState, useEffect, useCallback, useRef } from 'preact/hooks';
import {
  Button,
  Card,
  Field,
  Header,
  InLineAlert,
  Input,
  ProgressSpinner,
} from '@adobe-commerce/elsie/components';
import { useText } from '@adobe-commerce/elsie/i18n';
import { Tree, TreeItem } from '../Tree/Tree';
import { CompanyRoleModel, CompanyAclResourceModel } from '../../data/models/company-role';
import { flattenIdsToArray } from '../../lib/company-permissions';
import { 
  isCompanyRoleNameAvailable 
} from '../../api/companyRoles';
import './EditRoleAndPermission.css';

const ROLE_NAME_CONSTRAINTS = {
  MAX_LENGTH: 40,
  AUTO_TRUNCATE: true,
  ALLOW_SPECIAL_CHARS: true,
  CHECK_UNIQUENESS: true,
} as const;

const getRoleNameForSave = (raw: string): string => {
  const stringValue = typeof raw === 'string' ? raw : String(raw || '');
  const trimmed = stringValue.trim();
  return trimmed.slice(0, ROLE_NAME_CONSTRAINTS.MAX_LENGTH);
};

export interface EditRoleAndPermissionProps {
  mode: 'create' | 'edit';
  role?: CompanyRoleModel;
  aclResources: CompanyAclResourceModel[];
  existingRoleNames?: string[];
  loading?: boolean;
  onSubmit: (data: { name: string; permissions: string[] }) => void;
  onCancel: () => void;
  inLineAlertProps?: {
    type: 'success' | 'error' | 'warning';
    text: string;
    icon?: string;
  };
  prefillName?: string;
  prefillPermissions?: CompanyAclResourceModel[] | any[];
}

export const EditRoleAndPermission: FunctionComponent<EditRoleAndPermissionProps> = ({
  mode,
  role,
  aclResources,
  existingRoleNames = [],
  loading = false,
  onSubmit,
  onCancel,
  inLineAlertProps,
  prefillName,
  prefillPermissions,
}) => {
  const translations = useText({
    createTitle: 'Company.EditRoleAndPermission.createTitle',
    editTitle: 'Company.EditRoleAndPermission.editTitle',
    roleInformation: 'Company.EditRoleAndPermission.roleInformation',
    roleName: 'Company.EditRoleAndPermission.roleName',
    rolePermissions: 'Company.EditRoleAndPermission.rolePermissions',
    permissionsDescription: 'Company.EditRoleAndPermission.permissionsDescription',
    expandAll: 'Company.EditRoleAndPermission.expandAll',
    collapseAll: 'Company.EditRoleAndPermission.collapseAll',
    cancel: 'Company.shared.buttons.cancel',
    saveRole: 'Company.EditRoleAndPermission.saveRole',
    saving: 'Company.shared.buttons.saving',
    roleNameRequired: 'Company.shared.validation.roleNameRequired',
    roleNameExists: 'Company.shared.validation.roleNameExists',
  });

  const [formData, setFormData] = useState({
    name: role?.name || '',
  });

  const [errors, setErrors] = useState<Record<string, string>>({});
  const [touched, setTouched] = useState<Record<string, boolean>>({});
  const [isValidatingName, setIsValidatingName] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [treeItems, setTreeItems] = useState<TreeItem[]>([]);
  const [expandedIds, setExpandedIds] = useState<Set<string>>(new Set());
  const [selectedPermissions, setSelectedPermissions] = useState<Set<string>>(new Set());
  const validationTimeoutRef = useRef<number | null>(null);
  const lastValidatedNameRef = useRef<string>('');
  const isInitializedRef = useRef(false);

  useEffect(() => {
    // Only initialize form data once on mount, not on every prop change
    // This preserves user input when company switches and props update
    if (isInitializedRef.current) {
      return;
    }
    
    isInitializedRef.current = true;
    
    if (mode === 'edit' && role) {
      setFormData({ name: role.name });
      if (role.permissions && role.permissions.length > 0) {
        const permissionIds = flattenIdsToArray(role.permissions);
        setSelectedPermissions(new Set(permissionIds));
      }
    } else if (mode === 'create') {
      const nameToUse = prefillName ?? '';
      setFormData({ name: nameToUse });

      if (prefillPermissions && prefillPermissions.length > 0) {
        const permissionIds = flattenIdsToArray(prefillPermissions as any);
        setSelectedPermissions(new Set(permissionIds));
      } else {
        setSelectedPermissions(new Set());
      }
    }
  }, [mode, role, prefillName, prefillPermissions]);

  // Transform ACL resources to tree items
  useEffect(() => {
    if (aclResources.length > 0) {
      const items = transformAclResourcesToTreeItems(aclResources);
      setTreeItems(items);
      
      const rootIds = items
        .filter(item => !item.parentId)
        .map(item => item.id);
      
      setExpandedIds(new Set(rootIds));
      
    }
  }, [aclResources]);

  // Cleanup timeout on unmount
  useEffect(() => {
    return () => {
      if (validationTimeoutRef.current) {
        clearTimeout(validationTimeoutRef.current);
      }
    };
  }, []);

  const validateRoleName = useCallback((name: string): string | null => {
    const trimmedNameForSave = getRoleNameForSave(name);
    if (!trimmedNameForSave) {
      return translations.roleNameRequired || 'This is a required field.';
    }
    
    // Check uniqueness (exclude current role name in edit mode)
    const rolesToCheck = mode === 'edit' && role 
      ? existingRoleNames.filter(existingName => existingName !== role.name)
      : existingRoleNames;
      
    if (rolesToCheck.includes(trimmedNameForSave)) {
      return translations.roleNameExists;
    }
    
    return null;
  }, [mode, role, existingRoleNames, translations.roleNameRequired, translations.roleNameExists]);

  const validateRoleNameAsync = useCallback(async (name: string): Promise<string | null> => {
    const trimmedNameForSave = getRoleNameForSave(name);
    
    const basicError = validateRoleName(trimmedNameForSave);
    if (basicError) {
      return basicError;
    }
    
    if (mode === 'edit' && role && trimmedNameForSave === role.name) {
      return null;
    }
    
    try {
      setIsValidatingName(true);
      
      const isAvailable = await isCompanyRoleNameAvailable({ name: trimmedNameForSave });
      
      if (!isAvailable) {
        return translations.roleNameExists;
      }
      
      return null;
    } catch (error) {
      console.error('Role name validation failed:', error);
      // Allow submission and rely on backend validation
      return null;
    } finally {
      setIsValidatingName(false);
    }
  }, [mode, role, translations.roleNameExists, validateRoleName]);

  const debouncedValidateRoleName = useCallback((name: string) => {
    if (validationTimeoutRef.current !== null) {
      clearTimeout(validationTimeoutRef.current);
    }

    if (name === lastValidatedNameRef.current) {
      return;
    }

    validationTimeoutRef.current = window.setTimeout(async () => {
      const error = await validateRoleNameAsync(name);
      if (error) {
        setErrors(prev => ({ ...prev, name: error }));
      } else {
        setErrors(prev => ({ ...prev, name: '' }));
      }
      lastValidatedNameRef.current = name;
    }, 500);
  }, [validateRoleNameAsync]);

  const validateForm = (): boolean => {
    const newErrors: Record<string, string> = {};
    let isValid = true;

    const nameError = validateRoleName(formData.name);
    if (nameError) {
      newErrors.name = nameError;
      isValid = false;
    }

    setErrors(newErrors);
    return isValid;
  };

  const handleRoleNameChange = (value: string | Event) => {
    const stringValue = typeof value === 'string' ? value : (value.target as HTMLInputElement).value;
    setFormData(prev => ({ ...prev, name: stringValue }));
    
    if (errors.name) {
      setErrors(prev => ({ ...prev, name: '' }));
    }
    
    // Trigger debounced validation for real-time feedback
    debouncedValidateRoleName(stringValue);
  };

  const handleRoleNameBlur = () => {
    setTouched(prev => ({ ...prev, name: true }));
    
    // Cancel any pending debounced validation
    if (validationTimeoutRef.current) {
      clearTimeout(validationTimeoutRef.current);
      validationTimeoutRef.current = null;
    }
  };

  const handleExpandAll = () => {
    const allIds = new Set(treeItems.map(item => item.id));
    setExpandedIds(allIds);
  };

  const handleCollapseAll = () => {
    setExpandedIds(new Set());
  };

  const handleSubmit = async (event: Event) => {
    event.preventDefault();
    
    // Early return if already submitting
    if (isSubmitting) {
      return;
    }
    
    setTouched({ name: true });
    
    // Do synchronous validation first
    if (!validateForm()) {
      return;
    }
    
    // If there's already an error from previous validation, don't submit
    if (errors.name) {
      return;
    }
    
    setIsSubmitting(true);
    
    try {
      const roleData = {
        name: getRoleNameForSave(formData.name),
        permissions: Array.from(selectedPermissions),
      };

      if (onSubmit) {
        await onSubmit(roleData);
      }
    } catch (error) {
      console.error('Form submission failed:', error);
    } finally {
      setIsSubmitting(false);
    }
  };

  const title = mode === 'create' ? translations.createTitle : translations.editTitle;

  return (
    <Card variant="secondary" className="edit-role-and-permission">
      <Header
        level={2}
        size="large"
        title={title}
        divider={false}
        className="edit-role-and-permission__title"
      />
      
      {inLineAlertProps?.text && (
        <InLineAlert
          className="edit-role-and-permission__notification"
          type={inLineAlertProps.type}
          variant="secondary"
          heading={inLineAlertProps.text}
          data-testid="editRoleInLineAlert"
        />
      )}

      <form className="edit-role-and-permission-form" onSubmit={handleSubmit}>
        <div className="edit-role-and-permission__section">
          <Header
            level={3}
            size="medium"
            title={translations.roleInformation || 'Role Information'}
            divider={false}
            className="edit-role-and-permission__section-title"
          />
          
            <Field
              label={translations.roleName || 'Role Name'}
              required
              error={touched.name && errors.name ? errors.name : undefined}
            >
              <Input
                type="text"
                name="roleName"
                value={formData.name}
                onChange={handleRoleNameChange}
                onBlur={handleRoleNameBlur}
                disabled={loading || isSubmitting}
                data-testid="roleNameInput"
                placeholder={translations.roleName || 'Role Name'}
                variant="primary"
                size="medium"
                maxLength={40}
              />
            </Field>
            {isValidatingName && (
              <div className="edit-role-and-permission__validation-spinner">
                <ProgressSpinner size="medium" />
              </div>
            )}
        </div>

        <div className="edit-role-and-permission__section">
          <Header
            level={3}
            size="medium"
            title={translations.rolePermissions}
            divider={false}
            className="edit-role-and-permission__section-title"
          />
          
          <InLineAlert
            type="info"
            variant="secondary"
            heading={translations.permissionsDescription}
            className="edit-role-and-permission__permissions-description"
          />

          <div className="edit-role-and-permission__tree-controls">
            <Button
              type="button"
              variant="tertiary"
              onClick={handleExpandAll}
              disabled={loading || isSubmitting}
            >
              {translations.expandAll}
            </Button>
            <Button
              type="button"
              variant="tertiary"
              onClick={handleCollapseAll}
              disabled={loading || isSubmitting}
            >
              {translations.collapseAll}
            </Button>
          </div>

          <div 
            className="edit-role-and-permission__tree-container"
            role="group"
            aria-label={translations.rolePermissions}
          >
                {treeItems.length > 0 ? (
            <Tree
              items={treeItems}
              expandedIds={expandedIds}
              onExpandedChange={setExpandedIds}
              checkedIds={selectedPermissions}
              onCheckedChange={setSelectedPermissions}
              preserveOrder={true}
              isCheckable={() => true}
              biDirectionalChecking={true}
                      renderNode={({ item, expanded, hasChildren, toggle, checkbox }) => (
                        <div className="edit-role-and-permission__tree-node">
                          {hasChildren ? (
                            <button
                              type="button"
                              className="edit-role-and-permission__tree-expander"
                              onClick={(e) => {
                                e.preventDefault();
                                e.stopPropagation();
                                toggle();
                              }}
                              aria-label={expanded ? `Collapse ${item.label}` : `Expand ${item.label}`}
                            >
                              {expanded ? '−' : '+'}
                            </button>
                          ) : (
                            <span className="edit-role-and-permission__tree-spacer" />
                          )}
                          {checkbox && checkbox()}
                          <span className="edit-role-and-permission__tree-label">
                            {item.label}
                          </span>
                        </div>
                      )}
                    />
                ) : (
              <div className="edit-role-and-permission__tree-loading">
                Loading permissions...
              </div>
            )}
          </div>
        </div>

        <div className="edit-role-and-permission__actions">
          <Button
            type="button"
            variant="secondary"
            onClick={onCancel}
            disabled={loading || isSubmitting}
          >
            {translations.cancel}
          </Button>
          <Button
            type="submit"
            variant="primary"
            disabled={loading || isSubmitting}
          >
            {(loading || isSubmitting) ? translations.saving : translations.saveRole}
          </Button>
        </div>
      </form>

      {(loading || isSubmitting) && (
        <div className="edit-role-and-permission__loading-overlay">
          <ProgressSpinner size="large" />
          <div className="edit-role-and-permission__loading-text">
            {translations.saving}
          </div>
        </div>
      )}
    </Card>
  );
};

const transformAclResourcesToTreeItems = (resources: CompanyAclResourceModel[]): TreeItem[] => {
  const items: TreeItem[] = [];

  const processResource = (resource: CompanyAclResourceModel, parentId?: string) => {
    items.push({
      id: resource.id,
      parentId: parentId || null,
      label: resource.text,
    });

    if (resource.children) {
      // Sort children by sortOrder before processing to match Magento backend ordering
      const sortedChildren = [...resource.children].sort((a, b) => a.sortOrder - b.sortOrder);
      sortedChildren.forEach(child => {
        processResource(child, resource.id);
      });
    }
  };

  // Sort root resources by sortOrder before processing to match Magento backend ordering
  const sortedResources = [...resources].sort((a, b) => a.sortOrder - b.sortOrder);
  sortedResources.forEach(resource => processResource(resource));
  
  return items;
};
